export const escapeHtml=(v="")=>String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"})[c]);
export function MissionProgress({current,total,scenes}){const p=Math.round((current+1)/total*100);return `<div class="mission-progress" role="progressbar" aria-valuemin="1" aria-valuemax="${total}" aria-valuenow="${current+1}"><span><i style="width:${p}%"></i></span><b>${current+1} / ${total}</b><div class="mission-progress-steps">${scenes.map((s,i)=>`<span class="mission-step ${i<current?"done":i===current?"active":""}" title="${escapeHtml(s.phase)}"></span>`).join("")}</div></div>`;}
function Check(scene,r){if(!scene.check)return"";const c=r.checks[scene.id],a=scene.check.options.find(x=>x.id===c.selected);return `<section class="knowledge-check"><small>KNOWLEDGE CHECK</small><h3>${escapeHtml(scene.check.question)}</h3><div>${scene.check.options.map(x=>`<button type="button" data-check="${x.id}" class="${c.selected===x.id?"selected":""}">${escapeHtml(x.label)}</button>`).join("")}</div>${a?`<p class="${c.correct?"correct":"retry"}">${c.correct?"✓":"↻"} ${escapeHtml(a.feedback)}</p>`:""}</section>`;}
export function CharacterDialogue(s,r,off){const i=r.dialogue[s.id]||0,l=s.dialogue[i],style=`background-image:url('${escapeHtml(l.portrait)}');background-position:${escapeHtml(l.portraitPosition)}`;const brief=s.report?`<div class="incident-brief"><b>${escapeHtml(s.report.title)}</b><ul>${s.report.facts.map(x=>`<li>${escapeHtml(x)}</li>`).join("")}</ul><aside><strong>${escapeHtml(s.knowledge.title)}</strong><p>${escapeHtml(s.knowledge.text)}</p></aside><button type="button" data-action="accept-mission" ${r.accepted[s.id]?"disabled":""}>${r.accepted[s.id]?"✓ รับภารกิจแล้ว":"เปิดรายงานและรับภารกิจ"}</button></div>`:"";return `<article class="story-dialogue story-dialogue-rich"><div class="story-character-portrait" role="img" aria-label="${escapeHtml(l.speaker)}" style="${style}"></div><div class="dialogue-copy"><small>${escapeHtml(l.speaker)} · ${escapeHtml(l.role)}</small><h2>${escapeHtml(s.title)}</h2><p class="dialogue-text" data-dialogue-text="${escapeHtml(l.text)}">${off?escapeHtml(l.text):""}</p><div class="dialogue-navigation"><button data-action="dialogue-prev" ${i===0?"disabled":""}>← ก่อนหน้า</button><span>${i+1}/${s.dialogue.length}</span><button data-action="dialogue-next" ${i===s.dialogue.length-1?"disabled":""}>ถัดไป →</button></div>${off?"":'<button class="skip-text-effect" data-action="skip-text">แสดงข้อความทั้งหมด</button>'}${brief}</div></article>`;}
export function EvidenceViewer(s,r){const seen=r.evidence[s.id]||[],sel=s.evidence.find(x=>x.id===(r.selectedEvidence[s.id]||seen.at(-1)));return `<article class="evidence-panel"><div><small>${s.phase}</small><h2>${s.title}</h2><p>${s.body}</p></div>${sel?`<div class="evidence-detail"><span>${sel.marker}</span><div><b>${sel.title}</b><p>${sel.summary}</p><em>${sel.insight}</em></div></div>`:'<div class="evidence-empty">เลือกจุดบนฉากเพื่อเปิดหลักฐาน</div>'}<div class="evidence-count"><b>${seen.length}/${s.requiredEvidence}</b><span>หลักฐานที่ตรวจแล้ว</span></div>${seen.length>=s.requiredEvidence?Check(s,r):""}</article>`;}
export function KnowledgeCard(s){return `<article class="knowledge-card knowledge-card-rich"><span>⌁</span><div><small>${s.phase}</small><h2>${s.title}</h2><p>${s.body}</p><div class="knowledge-keywords">${s.keywords.map(x=>`<b>${x}</b>`).join("")}</div><div class="knowledge-snippets">${s.cards.map(x=>`<section><h3>${x.title}</h3><p>${x.text}</p></section>`).join("")}</div></div></article>`;}
export function SimulationPanel(s,r,result){const sim=r.simulation[s.id],controls=s.controls.map(c=>c.type==="range"?`<label class="simulation-control"><span>${c.label}<b data-control-value="${c.id}">${sim.values[c.id]}${c.unit}</b></span><input type="range" min="${c.min}" max="${c.max}" step="${c.step}" value="${sim.values[c.id]}" data-simulation-control="${c.id}"></label>`:`<label class="simulation-control"><span>${c.label}</span><select data-simulation-control="${c.id}">${c.options.map(o=>`<option value="${o.value}" ${o.value===sim.values[c.id]?"selected":""}>${o.label}</option>`).join("")}</select></label>`).join("");const out=result?`<div class="simulation-result risk-${result.risk==="ต่ำ"?"low":result.risk==="ปานกลาง"?"medium":"high"}"><div><small>ความพร้อม</small><strong>${result.readiness}</strong><span>/100</span></div><div><b>ความเสี่ยง ${result.risk}</b>${result.reasons.map(x=>`<p>• ${x}</p>`).join("")}</div></div>`:'<div class="simulation-empty">เลือกค่าหรือสถานการณ์ แล้วประมวลผล</div>';return `<article class="simulation-panel"><div><small>${s.phase}</small><h2>${s.title}</h2><p>${s.body}</p></div><div class="simulation-presets">${(s.presets||[]).map(x=>`<button data-preset="${x.id}">${x.label}</button>`).join("")}</div><div class="simulation-controls">${controls}</div><button class="simulation-run" data-action="run-simulation">ประมวลผล (${sim.runCount}/${s.requiredRuns||1})</button>${sim.history.length?`<div class="simulation-history">${sim.history.map((x,i)=>`<span><b>ครั้ง ${i+1}</b><i style="width:${x.readiness}%"></i><em>${x.readiness}/100</em></span>`).join("")}</div>`:""}${out}${sim.runCount>=(s.requiredRuns||1)?Check(s,r):""}</article>`;}
export function DecisionPanel(s,r,result){const d=r.decisions[s.id];return `<article class="decision-panel"><div><small>${s.phase}</small><h2>${s.title}</h2><p>${s.body}</p></div><div class="decision-options">${s.options.map(o=>`<button class="decision-option ${d.selected.includes(o.id)?"selected":""}" data-decision="${o.id}"><span>${d.selected.includes(o.id)?"✓":"+"}</span><div><b>${o.label}</b><small>${o.impact}</small></div></button>`).join("")}</div><button class="decision-submit" data-action="submit-decision" ${d.selected.length<s.minChoices?"disabled":""}>ยืนยันแนวทาง (${d.selected.length})</button>${result?`<div class="decision-feedback"><strong>${result.level}</strong>${result.impacts.map(x=>`<p>ประโยชน์: ${x}</p>`).join("")}${result.remainingRisks.map(x=>`<p>ความเสี่ยงคงเหลือ: ${x}</p>`).join("")}${result.allSelected?"<p>การเลือกทุกข้อไม่แทนการชั่งน้ำหนักผลกระทบ</p>":""}</div>${Check(s,r)}`:""}</article>`;}
export function MissionSummary(s,r){const evidence=Object.values(r.evidence).reduce((n,x)=>n+x.length,0),runs=Object.values(r.simulation).reduce((n,x)=>n+x.runCount,0);return `<article class="mission-summary-card"><small>${s.phase}</small><h2>${s.title}</h2><p>${s.body}</p><div class="mission-summary-stats"><span><b>${evidence}</b>หลักฐาน</span><span><b>${runs}</b>การทดลอง</span><span><b>${Object.values(r.decisions).filter(x=>x.submitted).length}</b>การตัดสินใจ</span></div><ul>${s.takeaways.map(x=>`<li>${x}</li>`).join("")}</ul><div class="stage3-note">${s.quizReady?'<button data-action="start-quiz">เริ่มแบบทดสอบ 10 ข้อ</button><p>ไม่จำกัดเวลา · ผ่านเมื่อได้อย่างน้อย 8/10</p>':"แบบทดสอบท้ายบทเรียนยังไม่เปิดใช้งาน จึงยังไม่บันทึกว่าผ่านบทเรียนหรือให้รางวัล"}</div></article>`;}
export function SceneVisual(s,r,result){if(s.evidence){const seen=r.evidence[s.id]||[];return `<div class="evidence-scene" style="background-image:linear-gradient(#1f5b8018,#40378033),url('${s.image}')">${s.evidence.map(x=>`<button class="evidence-hotspot ${seen.includes(x.id)?"checked":""}" data-evidence="${x.id}" style="left:${x.x}%;top:${x.y}%"><span>${seen.includes(x.id)?"✓":x.marker}</span></button>`).join("")}</div>`;}if(s.controls){return `<div class="simulation-visual"><div class="simulation-core" style="--readiness:${(result?.readiness||0)*3.6}deg"><span>AI</span><b>${result?.readiness??"—"}</b></div><div class="simulation-orbits"><i></i><i></i><i></i></div><p>${result?`ความเสี่ยง: ${result.risk}`:"รอผลการทดลอง"}</p></div>`;}if(s.options)return `<div class="decision-visual"><span>?</span><h3>RESPONSIBLE AI</h3><p>ชั่งน้ำหนักประโยชน์และความเสี่ยง</p></div>`;return `<div class="scene-visual" style="--scene-accent:${s.accent||"#7b75e8"}"><div class="scene-orbit"><i></i><i></i><i></i><strong>${s.type==="summary"?"6": "AI"}</strong></div><div class="scene-node-row"><span>ข้อมูล</span><span>ความเป็นธรรม</span><span>มนุษย์กำกับ</span></div></div>`;}
export function SceneExplanation(s,req){return `<aside class="scene-explanation"><b>คำแนะนำภารกิจ</b><p>${s.prompt}</p><span class="scene-requirement ${req.ready?"ready":"pending"}">${req.ready?"✓":"○"} ${req.message}</span></aside>`;}
